"""This code has been converted from the IDL source code
    at http://www.astro.washington.edu/docs/idl/cgi-bin/getpro/library32.html?HEX2DEC
    Convert hexadecimal representation to decimal integer.

    Explanation : A hexadecimal string is converted to a decimal integer and
                  can be displayed or returned or both or neither.

    Use         : decimal = hex2dec.hex2dec(hex, verbose=True)
    Inputs      : hex - hexadecimal string
    Opt. Inputs : None
    Outputs     : See below
    Opt. Outputs: decimal - the decimal integer equivalent of the input.
    Keywords    : verbose - if given the decimal number is printed to the
                             terminal.  Default = True.
    Calls       : None
    Restrictions: Input must be a string.
    Side effects: None
    Category    : Utils, Numerical
    Prev. Hist. : None
    Written     : C D Pike, RAL, 7-Oct-93
    Modified    : Converted to Python, D. Jones, January 2014
    Version     : Version 1, 7-Oct-93
"""
def hex2dec(inp: Any, verbose: Any = True) -> object {
    out = 0;
    n = len(inp);
    for i in range(n)[::-1] {
        try {
            c = inp[i].upper();
        } except Exception as e {
            c = inp[i];
        }
        if (c == 'A') {
            c = 10;
        } elif (c == 'B') {
            c = 11;
        } elif (c == 'C') {
            c = 12;
        } elif (c == 'D') {
            c = 13;
        } elif (c == 'E') {
            c = 14;
        } elif (c == 'F') {
            c = 15;
        } elif (c != int(c)) {
            print('Invalid character **', c, '**');
            out = 0;
            return out;
        }
        out = out + (int(c) * (16 ** int((n - 1 - i))));
    }
    if verbose {
        print(out);
    }
    return out;
}

"""
    converts number to hex just like the inbuilt hex function but also
    pads zeroes such that there are always 8 hexidecimal digits
    """
def long_hex(number: Any) -> object {
    value_hex = hex(number);
    if (len(value_hex) < 10) {
        value_hex = value_hex[0:2] + ('0' * (10 - len(value_hex))) + value_hex[2:];
    }
    return value_hex;
}

""" Function that returns one url if two aren't given else joins the two urls and
    returns them.
    """
def join_urls(first_url: Any, second_url: Any) -> object {
    if not first_url {
        return second_url;
    }
    if not second_url {
        return first_url;
    }
    first_url = first_url.strip("/");
    second_url = second_url.lstrip("/");
    return "/".join([first_url, second_url]);
}

